<?php use Hls\Http\View as V; ?>
<?php if($access->can('inventory.warehouse.create')): ?><section class="panel"><form method="post" class="form-grid"><?= $this->csrf() ?><label>Kode gudang<input name="code" maxlength="40" required></label><label>Nama gudang<input name="name" maxlength="150" required></label><label>Cabang<select name="branch_id" required><?php foreach($branches as $b): if($access->branch((int)$b['id'])): ?><option value="<?= (int)$b['id'] ?>"><?= V::escape($b['code'].' - '.$b['name']) ?></option><?php endif; endforeach ?></select></label><label>Lokasi<input name="location"></label><label>Keterangan<textarea name="note"></textarea></label><button class="button button-primary">Simpan Gudang</button></form></section><?php endif ?><section class="panel"><form method="get" class="filter-grid"><label>Pencarian<input name="q" value="<?= V::escape($q) ?>" placeholder="Kode atau nama"></label><label>Cabang<select name="branch_id"><option value="0">Semua cabang</option><?php foreach($branches as $b): if($access->branch((int)$b['id'])): ?><option value="<?= (int)$b['id'] ?>" <?= $branch_id==(int)$b['id']?'selected':'' ?>><?= V::escape($b['code'].' - '.$b['name']) ?></option><?php endif; endforeach ?></select></label><button class="button button-primary">Cari</button></form></section><section class="panel table-panel"><div class="table-wrap"><table><thead><tr><th>Kode</th><th>Nama</th><th>Cabang</th><th>Lokasi</th><th>Status</th><th>Aksi</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><?= V::escape($r['code']) ?></td><td><?= V::escape($r['name']) ?></td><td><?= V::escape($r['branch_code'].' - '.$r['branch_name']) ?></td><td><?= V::escape((string)$r['location']) ?></td><td><?= (int)$r['active']===1?'Aktif':'Nonaktif' ?></td><td><?php if($access->can('inventory.warehouse.update')): ?><details><summary>Edit</summary><form method="post" action="<?= $this->url('/inventory/warehouse-update') ?>" class="form-grid"><?= $this->csrf() ?><input type="hidden" name="id" value="<?= (int)$r['id'] ?>"><label>Kode<input name="code" value="<?= V::escape($r['code']) ?>" required></label><label>Nama<input name="name" value="<?= V::escape($r['name']) ?>" required></label><label>Cabang<select name="branch_id"><?php foreach($branches as $b): if($access->branch((int)$b['id'])): ?><option value="<?= (int)$b['id'] ?>" <?= (int)$r['branch_id']===(int)$b['id']?'selected':'' ?>><?= V::escape($b['code']) ?></option><?php endif; endforeach ?></select></label><label>Lokasi<input name="location" value="<?= V::escape((string)$r['location']) ?>"></label><label>Keterangan<input name="note" value="<?= V::escape((string)$r['note']) ?>"></label><button class="button">Simpan Perubahan</button></form><form method="post" action="<?= $this->url('/inventory/warehouse-status') ?>"><?= $this->csrf() ?><input type="hidden" name="id" value="<?= (int)$r['id'] ?>"><input type="hidden" name="active" value="<?= (int)$r['active']===1?0:1 ?>"><button class="button"><?= (int)$r['active']===1?'Nonaktifkan':'Aktifkan' ?></button></form></details><?php endif ?></td></tr><?php endforeach ?><?php if(!$rows): ?><tr><td colspan="6" class="empty-state">Belum ada gudang.</td></tr><?php endif ?></tbody></table></div></section>
